/// Which regions touch (both ways), by land, over a river crossing or by boat.
pub fn adjacent(id: &str) -> &'static [&'static str] {
    match id {
        "castillo" => &["bosque", "cantera", "cubil", "cueva", "madriguera", "villa"],
        "villa" => &["bosque", "caleta", "castillo", "cienaga", "claro", "madriguera"],
        "cueva" => &["cantera", "castillo", "cubil", "nido"],
        "bosque" => &["castillo", "claro", "cubil", "penascal", "puerta", "villa"],
        "claro" => &["bosque", "cienaga", "desembocadura", "puerta", "vado", "villa"],
        "madriguera" => &["caleta", "cantera", "castillo", "villa"],
        "cantera" => &["castillo", "cueva", "madriguera"],
        "caleta" => &["cienaga", "desembocadura", "madriguera", "villa"],
        "cienaga" => &["caleta", "claro", "desembocadura", "villa"],
        "desembocadura" => &["caleta", "cienaga", "claro", "ribera", "vado"],
        "penascal" => &["bosque", "cubil", "nido", "paso", "puerta"],
        "nido" => &["cubil", "cueva", "penascal"],
        "cubil" => &["bosque", "castillo", "cueva", "nido", "penascal"],
        "paso" => &["minas", "penascal", "puerta"],
        "puerta" => &["bosque", "cabeza", "claro", "paso", "penascal", "vado"],
        "vado" => &["claro", "desembocadura", "puerta", "ribera"],
        "marca" => &["cabeza", "minas", "molinoalto", "monasterio", "valdesanto"],
        "cabeza" => &["marca", "molinoalto", "puerta", "trigales"],
        "trigales" => &["cabeza", "molinoalto", "puerto_santo", "ribera"],
        "molinoalto" => &["cabeza", "marca", "puerto_santo", "trigales", "valdesanto"],
        "ribera" => &["desembocadura", "trigales", "vado"],
        "valdesanto" => &["marca", "molinoalto", "monasterio", "puerto_santo"],
        "monasterio" => &["capital", "marca", "minas", "valdesanto"],
        "puerto_santo" => &["molinoalto", "trigales", "valdesanto"],
        "capital" => &["minas", "monasterio"],
        "minas" => &["capital", "marca", "monasterio", "paso"],
        _ => &[],
    }
}

/// How an army gets across between two regions where it is not plain land.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Crossing {
    /// The Trolls' bridge: the wall at its end has to be taken.
    Puente,
    /// Wading through the reeds: it takes the whole day.
    Vado,
    /// The mountain pass by the lake: the cold and the climb cost men.
    Paso,
    /// By boat along the coast: it takes the whole day.
    Mar,
}

/// The crossings: (one side, the other, how, its name).
pub static CROSSINGS: [(&str, &str, Crossing, &str); 5] = [
    ("puerta", "cabeza", Crossing::Puente, "El Puente de los Trolls"),
    ("vado", "ribera", Crossing::Vado, "El Vado de los Juncos"),
    ("paso", "minas", Crossing::Paso, "El Paso del Lago"),
    ("desembocadura", "caleta", Crossing::Mar, "La ruta de las barcas"),
    ("desembocadura", "ribera", Crossing::Mar, "La ruta de las barcas"),
];

/// The crossing between two regions, if they meet over one.
pub fn crossing(a: &str, b: &str) -> Option<(Crossing, &'static str)> {
    CROSSINGS
        .iter()
        .find(|c| (c.0 == a && c.1 == b) || (c.0 == b && c.1 == a))
        .map(|c| (c.2, c.3))
}

